import React, { useState, useEffect } from 'react';
import { 
  Bus, 
  User, 
  ShieldCheck, 
  Mail, 
  Lock, 
  Phone, 
  Eye, 
  EyeOff, 
  ArrowRight,
  CheckCircle2,
  KeyRound,
  ArrowLeft
} from 'lucide-react';
import Footer from './Footer';

export default function Signin({ onLoginSuccess }) {
  const [role, setRole] = useState('user');
  const [mode, setMode] = useState('signin');

  const initialFormState = {
    name: '',
    emailOrPhone: '',
    phone: '',
    password: '',
    confirmPassword: '',
  };

  const [formData, setFormData] = useState(initialFormState);
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [loading, setLoading] = useState(false);

  const API_BASE = 'http://localhost:5000/api';

  const resetForm = () => {
    setFormData({
      name: '',
      emailOrPhone: '',
      phone: '',
      password: '',
      confirmPassword: '',
    });
    setError('');
    setSuccessMsg('');
    setShowPassword(false);
  };

  useEffect(() => {
    resetForm();
  }, []);

  const handleRoleChange = (selectedRole) => {
    if (role !== selectedRole) {
      setRole(selectedRole);
      resetForm();
    }
  };

  const handleModeChange = (newMode) => {
    setMode(newMode);
    resetForm();
  };

  const handleInputChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccessMsg('');

    if (mode === 'forgot') {
      if (!formData.emailOrPhone) {
        setError('Please enter your Mobile Number or Email Address.');
        return;
      }
      setSuccessMsg(`Password reset link/OTP sent to ${formData.emailOrPhone}`);
      return;
    }

    if (mode === 'signup') {
      if (!formData.name || !formData.emailOrPhone || !formData.password || !formData.confirmPassword) {
        setError('Please fill in all required registration fields.');
        return;
      }
      if (formData.password !== formData.confirmPassword) {
        setError('Passwords do not match!');
        return;
      }
      if (formData.password.length < 6) {
        setError('Password must be at least 6 characters.');
        return;
      }

      setLoading(true);

      const saveUserToLocalStorage = (userObj) => {
        const existingUsers = JSON.parse(localStorage.getItem('app_users') || '[]');
        const userExists = existingUsers.some((u) => u.email === userObj.email);

        if (!userExists) {
          existingUsers.push(userObj);
          localStorage.setItem('app_users', JSON.stringify(existingUsers));
        }
      };

      try {
        const response = await fetch(`${API_BASE}/signup`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            name: formData.name,
            email: formData.emailOrPhone,
            phone: formData.phone,
            password: formData.password,
            role: role,
          }),
        });

        const contentType = response.headers.get('content-type');
        if (!contentType || !contentType.includes('application/json')) {
          throw new Error('Backend server is unreachable or returned invalid non-JSON response.');
        }

        const data = await response.json();
        if (!response.ok) throw new Error(data.message || 'Registration failed.');

        saveUserToLocalStorage({
          id: data.user?.id || 'USR-' + Math.floor(1000 + Math.random() * 9000),
          name: formData.name,
          email: formData.emailOrPhone,
          phone: formData.phone,
          password: formData.password,
          role: role === 'admin' ? 'admin' : 'Passenger',
          joined: new Date().toISOString().split('T')[0],
          status: 'Active'
        });

        resetForm();
        setMode('signin');
        setSuccessMsg('Account saved permanently to database! You can now sign in.');

      } catch (err) {
        setError(err.message || 'Failed to communicate with database.');
      } finally {
        setLoading(false);
      }
      return;
    }

    if (mode === 'signin') {
      if (!formData.emailOrPhone || !formData.password) {
        setError('Please enter your Email and Password.');
        return;
      }

      setLoading(true);
      try {
        const response = await fetch(`${API_BASE}/signin`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            email: formData.emailOrPhone,
            password: formData.password,
            role: role,
          }),
        });

        const contentType = response.headers.get('content-type');
        if (!contentType || !contentType.includes('application/json')) {
          throw new Error('Server returned non-JSON response. Ensure Express backend is running on port 5000.');
        }

        const data = await response.json();
        if (!response.ok) throw new Error(data.message || 'Invalid login credentials.');

        localStorage.setItem('currentUser', JSON.stringify(data.user));

        if (onLoginSuccess) {
          onLoginSuccess(data.user);
        }
      } catch (err) {
        setError(err.message || 'Database login failed. Check credentials or server status.');
      } finally {
        setLoading(false);
      }
    }
  };

  return (
    <div style={styles.pageContainer}>
      {/* Form Container Section */}
      <div style={styles.formSection}>
        <div style={styles.authWrapper}>

          {/* LEFT PANEL */}
          <div style={styles.leftSection}>
            <div style={styles.brandGroup}>
              <div style={styles.logoBadge}>
                <Bus size={28} color="#18181b" />
              </div>
              <div>
                <h1 style={styles.leftTitle}>ONLINE BUS</h1>
                <span style={styles.bdBadge}>BANGLADESH</span>
              </div>
            </div>

            <div style={styles.leftHeroContent}>
              <h2 style={styles.heroHeading}>Travel across Bangladesh smoothly.</h2>
              <p style={styles.heroSubtext}>
                Book AC & Non-AC bus seats across Dhaka, Chattogram, Sylhet, Cox's Bazar, and all major divisions.
              </p>

              <div style={styles.featureList}>
                <div style={styles.featureItem}>
                  <CheckCircle2 size={18} color="#a1a1aa" />
                  <span>Real-time interactive seat selection</span>
                </div>
                <div style={styles.featureItem}>
                  <CheckCircle2 size={18} color="#a1a1aa" />
                  <span>bKash, Nagad, Rocket & Card payments</span>
                </div>
                <div style={styles.featureItem}>
                  <CheckCircle2 size={18} color="#a1a1aa" />
                  <span>Instant SMS verification & E-Ticket download</span>
                </div>
              </div>
            </div>

            <div style={styles.leftFooter}>
              © {new Date().getFullYear()} Online Bus Bangladesh. All rights reserved.
            </div>
          </div>

          {/* RIGHT PANEL */}
          <div style={styles.rightSection}>
            
            {/* Role Toggle */}
            <div style={styles.roleToggle}>
              <button
                type="button"
                onClick={() => handleRoleChange('user')}
                style={{ ...styles.roleBtn, ...(role === 'user' ? styles.activeRole : {}) }}
              >
                <User size={16} /> Passenger
              </button>
              <button
                type="button"
                onClick={() => handleRoleChange('admin')}
                style={{ ...styles.roleBtn, ...(role === 'admin' ? styles.activeRole : {}) }}
              >
                <ShieldCheck size={16} /> Admin Portal
              </button>
            </div>

            {/* Form Header */}
            <div style={styles.formHeader}>
              <h2 style={styles.formTitle}>
                {mode === 'forgot' && 'Reset Password'}
                {mode === 'signup' && `Create ${role === 'admin' ? 'Admin' : 'Passenger'} Account`}
                {mode === 'signin' && `${role === 'admin' ? 'Admin' : 'Passenger'} Sign In`}
              </h2>
              <p style={styles.formSubtext}>
                {mode === 'forgot' && 'Enter your registered Email/Mobile to receive reset instructions.'}
                {mode === 'signup' && 'Fill details below to register permanently in the database.'}
                {mode === 'signin' && `Enter your ${role === 'admin' ? 'Admin credentials' : 'Mobile Number or Email'} to proceed.`}
              </p>
            </div>

            {/* Alert Messages */}
            {error && <div style={styles.errorAlert}>{error}</div>}
            {successMsg && <div style={styles.successAlert}>{successMsg}</div>}

            {/* Input Form */}
            <form onSubmit={handleSubmit} style={styles.form} method="POST">

              {mode === 'signup' && (
                <div style={styles.inputGroup}>
                  <label style={styles.label}>Full Name</label>
                  <div style={styles.inputWrapper}>
                    <User size={18} style={styles.inputIcon} />
                    <input
                      type="text"
                      name="name"
                      placeholder="e.g. Tanvir Hossain"
                      value={formData.name}
                      onChange={handleInputChange}
                      style={styles.input}
                      autoComplete="name"
                    />
                  </div>
                </div>
              )}

              <div style={styles.inputGroup}>
                <label style={styles.label}>
                  {mode === 'signup' ? 'Email Address' : 'Mobile Number or Email'}
                </label>
                <div style={styles.inputWrapper}>
                  <Mail size={18} style={styles.inputIcon} />
                  <input
                    type="text"
                    name="emailOrPhone"
                    placeholder={
                      mode === 'signup' 
                        ? 'passenger@example.com' 
                        : role === 'admin' 
                          ? 'admin@gmail.com' 
                          : '017XXXXXXXX or user@gmail.com'
                    }
                    value={formData.emailOrPhone}
                    onChange={handleInputChange}
                    style={styles.input}
                    autoComplete="email"
                    required
                  />
                </div>
              </div>

              {mode === 'signup' && (
                <div style={styles.inputGroup}>
                  <label style={styles.label}>Mobile Number</label>
                  <div style={styles.inputWrapper}>
                    <Phone size={18} style={styles.inputIcon} />
                    <input
                      type="tel"
                      name="phone"
                      placeholder="01712345678"
                      value={formData.phone}
                      onChange={handleInputChange}
                      style={styles.input}
                      autoComplete="tel"
                    />
                  </div>
                </div>
              )}

              {mode !== 'forgot' && (
                <div style={styles.inputGroup}>
                  <label style={styles.label}>Password</label>
                  <div style={styles.inputWrapper}>
                    <Lock size={18} style={styles.inputIcon} />
                    <input
                      type={showPassword ? 'text' : 'password'}
                      name="password"
                      placeholder="••••••••"
                      value={formData.password}
                      onChange={handleInputChange}
                      style={styles.input}
                      autoComplete={mode === 'signup' ? 'new-password' : 'current-password'}
                      required
                    />
                    <button
                      type="button"
                      onClick={() => setShowPassword(!showPassword)}
                      style={styles.eyeBtn}
                    >
                      {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                    </button>
                  </div>

                  {mode === 'signin' && (
                    <div style={styles.forgotRow}>
                      <button
                        type="button"
                        onClick={() => handleModeChange('forgot')}
                        style={styles.forgotBtn}
                      >
                        Forgot password?
                      </button>
                    </div>
                  )}
                </div>
              )}

              {mode === 'signup' && (
                <div style={styles.inputGroup}>
                  <label style={styles.label}>Confirm Password</label>
                  <div style={styles.inputWrapper}>
                    <Lock size={18} style={styles.inputIcon} />
                    <input
                      type={showPassword ? 'text' : 'password'}
                      name="confirmPassword"
                      placeholder="••••••••"
                      value={formData.confirmPassword}
                      onChange={handleInputChange}
                      style={styles.input}
                      autoComplete="new-password"
                    />
                  </div>
                </div>
              )}

              <button type="submit" style={styles.submitBtn} disabled={loading}>
                {loading ? (
                  <span>Saving to Database...</span>
                ) : (
                  <>
                    {mode === 'forgot' && (
                      <>
                        <KeyRound size={18} /> Send Reset Link
                      </>
                    )}
                    {mode === 'signup' && (
                      <>
                        <span>Register Account</span> <ArrowRight size={18} />
                      </>
                    )}
                    {mode === 'signin' && (
                      <>
                        <span>Sign In as {role === 'admin' ? 'Admin' : 'Passenger'}</span> <ArrowRight size={18} />
                      </>
                    )}
                  </>
                )}
              </button>
            </form>

            <div style={styles.switchContainer}>
              {mode === 'forgot' ? (
                <button
                  type="button"
                  onClick={() => handleModeChange('signin')}
                  style={styles.backBtn}
                >
                  <ArrowLeft size={16} /> Back to Sign In
                </button>
              ) : (
                <>
                  <span>{mode === 'signup' ? 'Already registered?' : "Don't have an account?"}</span>
                  <button
                    type="button"
                    onClick={() => handleModeChange(mode === 'signup' ? 'signin' : 'signup')}
                    style={styles.switchBtn}
                  >
                    {mode === 'signup' ? 'Sign In' : 'Sign Up'}
                  </button>
                </>
              )}
            </div>

          </div>
        </div>
      </div>

      {/* Full Width Footer Component */}
      <Footer />
    </div>
  );
}

const styles = {
  pageContainer: {
    minHeight: '100vh',
    width: '100%',
    backgroundColor: '#27272a',
    display: 'flex',
    flexDirection: 'column',
    boxSizing: 'border-box',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
  },
