    flex: 1,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '8px',
    padding: '8px 0',
    fontSize: '0.85rem',
    fontWeight: '600',
    border: 'none',
    borderRadius: '8px',
    backgroundColor: 'transparent',
    color: '#71717a',
    cursor: 'pointer',
  },
  activeRole: { backgroundColor: '#18181b', color: '#ffffff' },
  formHeader: { marginBottom: '16px' },
  formTitle: { fontSize: '1.4rem', fontWeight: '700', color: '#18181b', margin: '0 0 4px 0' },
